const COMPONENT_TYPES = ["rune"];
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;

const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

// Alike components are grouped into building blocks of 3, which carry a
// special base premium; leftovers are priced individually.
const componentsBasePremium = (components: Item[]): number => {
  const blocks = Math.floor(components.length / BUILDING_BLOCK_SIZE);
  const leftovers = components.length % BUILDING_BLOCK_SIZE;
  return (
    blocks * BUILDING_BLOCK_BASE_PREMIUM +
    leftovers * basePremiumOf(components[0])
  );
};

const totalBasePremium = (items: Item[]): number => {
  const components = items.filter(isComponent);
  const mainItems = items.filter((item) => !isComponent(item));
  const mainItemsTotal = mainItems.reduce(
    (total, item) => total + basePremiumOf(item),
    0,
  );
  if (components.length === 0) return mainItemsTotal;
  return mainItemsTotal + componentsBasePremium(components);
};

