  const groups = new Map<string, Item[]>();
  for (const item of items) {
    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
  }
  return [...groups.values()];
};

const totalBasePremium = (items: Item[]): number => {
  const components = items.filter(isComponent);
  const mainItems = items.filter((item) => !isComponent(item));
  const componentsTotal = groupByType(components).reduce(
    (total, alike) => total + alikeComponentsBasePremium(alike),
    0,
  );
  return sumBasePremiums(mainItems) + componentsTotal;
