export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResult {
  results: StepResult[];
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
// as a float rate (× 1.1): this keeps intermediate values integral and avoids
// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
// (100 * 110) / 100 is exact. Premiums round up in MHPCO's favour at the end.
const ONE_HUNDRED_PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const ADMIN_FEE = 5;

const applyPercent = (amount: number, percent: number): number =>
  (amount * percent) / ONE_HUNDRED_PERCENT;

const addSurcharge = (amount: number, surchargePercent: number): number =>
  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);

const COMPONENT_TYPES = ["rune", "moonstone"];
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;

const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item), 0);

// Alike components are grouped into building blocks of 3, which carry a
// special base premium; the remaining components are priced individually.
// Total over the empty group: no components means no blocks and no remainder.
const alikeComponentsBasePremium = (components: Item[]): number => {
  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
  return blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumBasePremiums(unblocked);
};

const totalBasePremium = (items: Item[]): number => {
  const components = items.filter(isComponent);
  const mainItems = items.filter((item) => !isComponent(item));
  return sumBasePremiums(mainItems) + alikeComponentsBasePremium(components);
};

const quote = (step: QuoteStep): QuoteResult => {
  const basePremium = totalBasePremium(step.items);
  const premiumAfterFirstInsurance = addSurcharge(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );
  return { premium: Math.ceil(premiumAfterFirstInsurance) + ADMIN_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(quote),
});

