// Contract-level modifiers adjust the sum insured by the terms of the deal
// rather than the nature of the items: the surcharge on a customer's first
// insurance, then the loyalty discount earned by long-standing customers.
const contractAdjustedPremiumOf = (
  sumInsured: number,
  customer: Customer,
): number => {
  const afterFirstInsurance = addSurcharge(
    sumInsured,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );
  return customer.yearsWithMHPCO >= LOYALTY_YEARS
    ? applyPercent(afterFirstInsurance, ONE_HUNDRED_PERCENT - LOYALTY_DISCOUNT_PERCENT)
    : afterFirstInsurance;
};

