export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResult {
  results: StepResult[];
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
// as a float rate (× 1.1): this keeps intermediate values integral and avoids
// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
// (100 * 110) / 100 is exact.
const ONE_HUNDRED_PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const ADMIN_FEE = 5;

const applyPercent = (amount: number, percent: number): number =>
  (amount * percent) / ONE_HUNDRED_PERCENT;

const addSurcharge = (amount: number, surchargePercent: number): number =>
  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);

const COMPONENT_TYPES = ["rune", "moonstone"];
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;
const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

// Risk surcharges are per-item properties of the insured object, each raising
// that item's premium by a percentage. They stack multiplicatively: an item
// matching two rules is surcharged by the first, then by the second.
interface RiskSurcharge {
  appliesTo: (item: Item) => boolean;
  percent: number;
}

const RISK_SURCHARGES: RiskSurcharge[] = [
  { appliesTo: (item) => item.cursed === true, percent: 50 },
  { appliesTo: (item) => (item.enchantment ?? 0) >= 5, percent: 30 },
];

const riskAdjustedPremiumOf = (item: Item): number =>
  RISK_SURCHARGES.reduce(
    (premium, surcharge) =>
      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
    basePremiumOf(item),
  );

const sumRiskAdjustedPremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);

// Alike components are grouped into building blocks of 3, which carry a
// special base premium; the remaining components are priced individually,
// risk surcharges and all.
// Total over the empty group: no components means no blocks and no remainder.
const alikeComponentsPremium = (components: Item[]): number => {
  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
  return (
    blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumRiskAdjustedPremiums(unblocked)
  );
};

const groupByType = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

// Components and main items are priced by different rules, so each group is
// totalled separately: components by building block, main items item by item.
const componentsPremium = (components: Item[]): number =>
  groupByType(components).reduce(
    (total, alike) => total + alikeComponentsPremium(alike),
    0,
  );

// The sum insured is what the items alone are worth to MHPCO, before any
// modifier that depends on the customer or the contract they sit in.
const sumInsuredOf = (items: Item[]): number =>
  sumRiskAdjustedPremiums(items.filter((item) => !isComponent(item))) +
  componentsPremium(items.filter(isComponent));

// Contract-level modifiers adjust the sum insured by the terms of the deal
// rather than the nature of the items. Today the only one is the surcharge
// on a customer's first insurance.
const contractAdjustedPremiumOf = (sumInsured: number): number =>
  addSurcharge(sumInsured, FIRST_INSURANCE_SURCHARGE_PERCENT);

// Premiums round up in MHPCO's favour, and the flat admin fee is added last
// so that no percentage ever applies to it.
const billableFrom = (premium: number): number =>
  Math.ceil(premium) + ADMIN_FEE;

const quote = (step: QuoteStep): QuoteResult => ({
  premium: billableFrom(contractAdjustedPremiumOf(sumInsuredOf(step.items))),
});

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(quote),
});

