      steps: [swordQuote, swordQuote, swordQuote],
    });

    expect(result).toEqual({
      results: [{ premium: 115 }, { premium: 90 }, { premium: 90 }],
    });
  });
  it.todo("combines loyalty and subsequent-contract discounts — 5-year customer's second sword 100*0.85*0.8 = 68 +5 = 73 G");

  // --- Quote: rounding ---
  it.todo("rounds the premium up in MHPCO's favor — 5-year customer's first amulet 60*1.1*0.8 = 52.8 -> 53 +5 = 58 G");

  // --- Claim: deductible and reimbursement rules ---
  it.todo("pays the damage minus the 100 G deductible — 200 G damage on an amulet policy pays 100 G");
