  it.todo("fully reimburses damage to an item made of dragon material — 400 G damage pays 300 G");
  it.todo("reports the remaining cap of twice the insurance sum after a claim — amulet policy 1200 cap, 100 G payout leaves 1100 G");
  it.todo("reduces the remaining cap across successive claims on the same policy — second claim of 250 G pays 150 G leaving 950 G");
