// so the rule dividing them is written exactly once.
const partition = (
  items: Item[],
  matches: (item: Item) => boolean,
): [Item[], Item[]] =>
  items.reduce<[Item[], Item[]]>(
    ([matching, rest], item) =>
      matches(item) ? [[...matching, item], rest] : [matching, [...rest, item]],
    [[], []],
  );

