  groupByType(components).reduce(
    (total, alike) => total + alikeComponentsPremium(alike),
    0,
  );

// The sum insured is what the items alone are worth to MHPCO, before any
// modifier that depends on the customer or the contract they sit in. Every
// item is either a component or a main item — the split is stated once, as a
// partition, so the two halves cannot drift apart — and each half is priced by
// its own rules.
const sumInsuredOf = (items: Item[]): number => {
  const [components, mainItems] = partition(items, isComponent);
  return sumRiskAdjustedPremiums(mainItems) + componentsPremium(components);
};

