  sumInsured: number,
  contract: Contract,
): number =>
  CONTRACT_MODIFIERS.reduce(
    (premium, modifier) =>
      modifier.appliesTo(contract) ? modifier.adjust(premium) : premium,
    standingAdjustedPremiumOf(sumInsured, contract),
  );

