// A quote creates a policy, which then absorbs claims: every payout draws down
// a cap of twice the sum insured, so the policy carries state between steps.
interface Policy {
  remainingCap: number;
}

const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
  const damageTotal = step.incident.damages.reduce(
    (total, damage) => total + damage.amount,
    0,
  );
  const payout = damageTotal - DEDUCTIBLE;
  return { payout, remainingCap: policy.remainingCap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy) as Policy;
      const result = claim(step, policy);
      policy.remainingCap = result.remainingCap;
      return result;
    }
    policies.set(index, {
      remainingCap: sumInsuredOf(step.items) * CAP_MULTIPLE,
    });
    return quote(step, {
      customer: scenario.customer,
      isFirstContract: index === 0,
    });
  });
  return { results };
};

