// However great the loss, a policy pays out only what it has left to give.
const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
  const payout = Math.min(
    netOfDeductible(reimbursementTotalOf(step.incident, policy)),
    policy.remainingCap,
  );
  return { payout, remainingCap: policy.remainingCap - payout };
};

